import{_ as i,a0 as d,w as c,s as l,I as n,x as o,a1 as t,A as a,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"無憂之道：Docker中容器的備份、恢復和遷移 | LCTT x X-CMD","titleTemplate":false,"description":"無憂之道：Docker中容器的備份、恢復和遷移 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"無憂之道：Docker中容器的備份、恢復和遷移 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"無憂之道：Docker中容器的備份、恢復和遷移 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150727 Easy Backup Restore and Migrate Containers in Docker","title":"無憂之道：Docker中容器的備份、恢復和遷移","tag":"201508","desc":""},"relativePath":"201508/20150727 Easy Backup Restore and Migrate Containers in Docker.md","filePath":"[post].md"}'),k={name:"201508/20150727 Easy Backup Restore and Migrate Containers in Docker.md"};function s(u,e,m,D,g,b){const r=d("Link");return c(),l("div",null,[e[19]||(e[19]=n("h1",{id:"無憂之道-docker中容器的備份、恢復和遷移",tabindex:"-1"},[o("無憂之道：Docker中容器的備份、恢復和遷移 "),n("a",{class:"header-anchor",href:"#無憂之道-docker中容器的備份、恢復和遷移","aria-label":"Permalink to “無憂之道：Docker中容器的備份、恢復和遷移”"},"​")],-1)),n("p",null,[e[1]||(e[1]=o("今天，我們將學習如何快速地對docker容器進行快捷備份、恢復和遷移。",-1)),t(r,{href:"http://docker.com/"},{default:a(()=>[...e[0]||(e[0]=[o("Docker",-1)])]),_:1}),e[2]||(e[2]=o("是一個開源平台，用於自動化部署應用，以通過快捷的途徑在稱之為容器的輕量級軟件層下打包、發佈和運行這些應用。它使得應用平台獨立，因為它扮演了Linux上一個額外的操作系統級虛擬化的自動化抽象層。它通過其組件cgroups和命名空間利用Linux內核的資源分離特性，達到避免虛擬機開銷的目的。它使得用於部署和擴展web應用、資料庫和後端服務的大規模構建組件無需依賴於特定的堆棧或供應者。",-1))]),e[20]||(e[20]=p(`<p>所謂的容器，就是那些創建自Docker鏡像的軟件層，它包含了獨立的Linux文件系統和開箱即用的應用程序。如果我們有一個在機器中運行着的Docker容器，並且想要備份這些容器以便今後使用，或者想要遷移這些容器，那麼，本教程將幫助你掌握在Linux操作系統中備份、恢復和遷移Docker容器的方法。</p><p>我們怎樣才能在Linux中備份、恢復和遷移Docker容器呢？這裏為您提供了一些便捷的步驟。</p><h3 id="_1-備份容器" tabindex="-1">1. 備份容器 <a class="header-anchor" href="#_1-備份容器" aria-label="Permalink to “1. 備份容器”">​</a></h3><p>首先，為了備份Docker中的容器，我們會想看看我們想要備份的容器列表。要達成該目的，我們需要在我們運行着Docker引擎，並已創建了容器的Linux機器中運行 docker ps 命令。</p><pre><code># docker ps
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/docker-containers-list.png" alt="Docker Containers List"></p><p>在此之後，我們要選擇我們想要備份的容器，然後去創建該容器的快照。我們可以使用 docker commit 命令來創建快照。</p><pre><code># docker commit -p 30b8f18f20b4 container-backup
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/docker-commit.png" alt="Docker Commit"></p><p>該命令會生成一個作為Docker鏡像的容器快照，我們可以通過運行 <code>docker images</code> 命令來查看Docker鏡像，如下。</p><pre><code># docker images
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/docker-images.png" alt="Docker Images"></p><p>正如我們所看見的，上面做的快照已經作為Docker鏡像保存了。現在，為了備份該快照，我們有兩個選擇，一個是我們可以登錄進Docker註冊中心，並推送該鏡像；另一個是我們可以將Docker鏡像打包成tar包備份，以供今後使用。</p>`,13)),n("p",null,[e[4]||(e[4]=o("如果我們想要在",-1)),t(r,{href:"https://registry.hub.docker.com/"},{default:a(()=>[...e[3]||(e[3]=[o("Docker註冊中心",-1)])]),_:1}),e[5]||(e[5]=o("上傳或備份鏡像，我們只需要運行 docker login 命令來登錄進Docker註冊中心，然後推送所需的鏡像即可。",-1))]),e[21]||(e[21]=p(`<pre><code># docker login
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/docker-login.png" alt="Docker Login"></p><pre><code># docker tag a25ddfec4d2a arunpyasi/container-backup:test
# docker push arunpyasi/container-backup
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/docker-push.png" alt="Docker Push"></p><p>如果我們不想備份到docker註冊中心，而是想要將此鏡像保存在本地機器中，以供日後使用，那麼我們可以將其作為tar包備份。要完成該操作，我們需要運行以下 <code>docker save</code> 命令。</p><pre><code># docker save -o ~/container-backup.tar container-backup
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/taking-tarball-backup.png" alt="taking tarball backup"></p><p>要驗證tar包是否已經生成，我們只需要在保存tar包的目錄中運行 ls 命令即可。</p><h3 id="_2-恢復容器" tabindex="-1">2. 恢復容器 <a class="header-anchor" href="#_2-恢復容器" aria-label="Permalink to “2. 恢復容器”">​</a></h3><p>接下來，在我們成功備份了我們的Docker容器後，我們現在來恢復這些製作了Docker鏡像快照的容器。如果我們已經在註冊中心推送了這些Docker鏡像，那麼我們僅僅需要把那個Docker鏡像拖回並直接運行即可。</p><pre><code># docker pull arunpyasi/container-backup:test
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/docker-pull.png" alt="Docker Pull"></p><p>但是，如果我們將這些Docker鏡像作為tar包文件備份到了本地，那麼我們只要使用 docker load 命令，後面加上tar包的備份路徑，就可以加載該Docker鏡像了。</p><pre><code># docker load -i ~/container-backup.tar
</code></pre><p>現在，為了確保這些Docker鏡像已經加載成功，我們來運行 docker images 命令。</p><pre><code># docker images
</code></pre><p>在鏡像被加載後，我們將用加載的鏡像去運行Docker容器。</p><pre><code># docker run -d -p 80:80 container-backup
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/restoring-docker-tarballs.png" alt="Restoring Docker Tarball"></p><h3 id="_3-遷移docker容器" tabindex="-1">3. 遷移Docker容器 <a class="header-anchor" href="#_3-遷移docker容器" aria-label="Permalink to “3. 遷移Docker容器”">​</a></h3><p>遷移容器同時涉及到了上面兩個操作，備份和恢復。我們可以將任何一個Docker容器從一台機器遷移到另一台機器。在遷移過程中，首先我們將把容器備份為Docker鏡像快照。然後，該Docker鏡像或者是被推送到了Docker註冊中心，或者被作為tar包文件保存到了本地。如果我們將鏡像推送到了Docker註冊中心，我們簡單地從任何我們想要的機器上使用 docker run 命令來恢復並運行該容器。但是，如果我們將鏡像打包成tar包備份到了本地，我們只需要拷貝或移動該鏡像到我們想要的機器上，加載該鏡像並運行需要的容器即可。</p><h3 id="尾聲" tabindex="-1">尾聲 <a class="header-anchor" href="#尾聲" aria-label="Permalink to “尾聲”">​</a></h3><p>最後，我們已經學習瞭如何快速地備份、恢復和遷移Docker容器，本教程適用於各個可以成功運行Docker的操作系統平台。真的，Docker是一個相當簡單易用，然而功能卻十分強大的工具。它的命令相當易記，這些命令都非常短，帶有許多簡單而強大的標記和參數。上面的方法讓我們備份容器時很是安逸，使得我們可以在日後很輕鬆地恢復它們。這會幫助我們恢復我們的容器和鏡像，即便主機系統崩潰，甚至意外地被清除。如果你還有很多問題、建議、反饋，請在下面的評論框中寫出來吧，可以幫助我們改進或更新我們的內容。謝謝大家！享受吧 😃</p><hr>`,24)),n("p",null,[e[7]||(e[7]=o("via: ",-1)),t(r,{href:"http://linoxide.com/linux-how-to/backup-restore-migrate-containers-docker/"},{default:a(()=>[...e[6]||(e[6]=[o("http://linoxide.com/linux-how-to/backup-restore-migrate-containers-docker/",-1)])]),_:1})]),n("p",null,[e[11]||(e[11]=o("作者：",-1)),t(r,{href:"http://linoxide.com/author/arunp/"},{default:a(()=>[...e[8]||(e[8]=[o("Arun Pyasi",-1)])]),_:1}),e[12]||(e[12]=o(" 譯者：",-1)),t(r,{href:"https://github.com/GOLinux"},{default:a(()=>[...e[9]||(e[9]=[o("GOLinux",-1)])]),_:1}),e[13]||(e[13]=o(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[o("wxy",-1)])]),_:1})]),n("p",null,[e[16]||(e[16]=o("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[14]||(e[14]=[o("LCTT",-1)])]),_:1}),e[17]||(e[17]=o(" 原創翻譯，",-1)),t(r,{href:"https://linux.cn/"},{default:a(()=>[...e[15]||(e[15]=[o("Linux中國",-1)])]),_:1}),e[18]||(e[18]=o(" 榮譽推出",-1))])])}const C=i(k,[["render",s]]);export{T as __pageData,C as default};
